function blocked(x,y){if(x<20||x>940||y<30||y>520)return true;for(const o of obstacles){const left=o.x-10,right=o.x+o.w+10,top=o.y+o.h*.63,bottom=o.y+o.h+4;if(x>left&&x<right&&y>top&&y<bottom)return true}if(Math.hypot(x-281,y-347)<58)return true;return false}
