function showItem(item){$('itemInfo').innerHTML=`<div class="item-emoji">${item.emoji}</div><h3>${item.name}</h3><p>${item.desc}</p>`;if(item.type==='heal'||item.type==='potion'){const b=document.createElement('button');b.className='btn primary';b.textContent=hero.inventory[item.emoji]?'Use item':'None left';b.disabled=!hero.inventory[item.emoji];b.onclick=()=>useItem(item);$('itemInfo').appendChild(b)}}
function useItem(item){if(!hero.inventory[item.emoji])return;if(hero.hp===hero.maxHp){showToast('Your hearts are already full!');return}const heal=item.type==='heal'?6:10;hero.hp=Math.min(hero.maxHp,hero.hp+heal);hero.inventory[item.emoji]--;updateHeroUI();renderInventory();showToast(`A little better. +${heal} hearts!`)}
function save(){const data={...hero,questStage,chestOpen:chest.open,slimes:slimes.map(s=>({hp:s.hp,alive:s.alive}))};try{localStorage.setItem('whisperwood-save',JSON.stringify(data));showToast('Journey saved safely in this browser.')}catch{showToast('Could not save — browser storage is unavailable.')}}
function load(){let data;try{data=JSON.parse(localStorage.getItem('whisperwood-save'))}catch{}if(!data){showToast('No saved journey found yet.');return false}Object.assign(hero,{name:data.name||'Rowan',role:data.role||'Ranger',color:data.color||'#8ac27c',x:data.x||478,y:data.y||325,hp:data.hp||20,maxHp:data.maxHp||20,gold:data.gold||0,level:data.level||1,xp:data.xp||0,inventory:data.inventory||{'🍎':3,'🧪':1,'🪵':2,'🪙':12}});questStage=data.questStage||0;chest.open=!!data.chestOpen;if(Array.isArray(data.slimes))data.slimes.forEach((s,i)=>{if(slimes[i])Object.assign(slimes[i],s)});started=true;updateHeroUI();showToast('Welcome back, '+hero.name+'.');openOverlay(null);return true}
$('newGame').onclick=()=>openOverlay('creator');$('continueGame').onclick=()=>{if(!load())openOverlay('creator')};$('creatorBack').onclick=()=>openOverlay('start');$('createHero').onclick=()=>{hero.name=$('nameInput').value.trim()||'Rowan';hero.role=document.querySelector('#classChoices .selected').dataset.class;hero.color=document.querySelector('#colorChoices .selected').dataset.color;hero.x=478;hero.y=325;hero.hp=20;hero.gold=12;hero.level=1;hero.xp=0;hero.inventory={'🍎':3,'🧪':1,'🪵':2,'🪙':12};questStage=0;chest.open=false;slimes.forEach(s=>{s.hp=3;s.alive=true});started=true;updateHeroUI();openOverlay(null);showToast('A new adventure begins, '+hero.name+'!')};
document.querySelectorAll('#classChoices .choice').forEach(b=>b.onclick=()=>{document.querySelectorAll('#classChoices .choice').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');$('previewSprite').textContent=spriteFor(b.dataset.class)});document.querySelectorAll('#colorChoices .swatch').forEach(b=>b.onclick=()=>{document.querySelectorAll('#colorChoices .swatch').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');$('preview').style.background=`radial-gradient(ellipse,${b.dataset.color}99,#344e3a 65%,#26372d)`});
$('invBtn').onclick=()=>{renderInventory();showItem(items.find(i=>i.emoji===selectedItem)||items[0]);openOverlay('inventory')};$('closeInventory').onclick=()=>openOverlay(null);$('inventorySave').onclick=save;$('saveTop').onclick=save;$('loadTop').onclick=()=>{if(!load())showToast('No saved journey found yet.')};$('interactBtn').onclick=act;$('touchInteract').onclick=act;$('touchAttack').onclick=()=>{const t=nearby();if(t?.type==='slime')attack(t.i);else act()};$('closeInventory').onclick=()=>openOverlay(null);
window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();if(e.key==='Escape'){if(!overlays.inventory.classList.contains('hidden')||!overlays.dialog.classList.contains('hidden'))openOverlay(null);else if(started)save();return}if((e.key==='i'||e.key==='I')&&started){if(overlays.inventory.classList.contains('hidden'))$('invBtn').click();else openOverlay(null);return}if(e.key==='e'||e.key==='E'||e.key==='Enter'){if(!overlays.dialog.classList.contains('hidden')){const b=$('dialogActions').querySelector('button');if(b)b.click()}else if(overlays.start.classList.contains('hidden')&&overlays.creator.classList.contains('hidden')&&overlays.inventory.classList.contains('hidden'))act();return}if(e.code==='Space'){const t=nearby();if(t?.type==='slime')attack(t.i);else act();return}keys[e.key]=true});window.addEventListener('keyup',e=>keys[e.key]=false);window.addEventListener('blur',()=>keys={});document.querySelectorAll('[data-dir]').forEach(b=>{const dir=b.dataset.dir,down=e=>{e.preventDefault();keys[{up:'ArrowUp',down:'ArrowDown',left:'ArrowLeft',right:'ArrowRight'}[dir]]=true},up=e=>{e.preventDefault();keys[{up:'ArrowUp',down:'ArrowDown',left:'ArrowLeft',right:'ArrowRight'}[dir]]=false};b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointerleave',up);b.addEventListener('pointercancel',up)});
